def _is_builtin_tool(tool: Any) -> bool:
    """Return whether a tool definition is a built-in (non-function) tool."""
    return isinstance(tool, dict) and "type" in tool and tool["type"] != "function"


def _use_responses_api(payload: dict) -> bool:
    """Determine whether a request payload should be routed to the Responses API.

    Args:
        payload: The request payload to inspect.

    Returns:
        `True` if the payload contains a built-in tool (a tool whose `type` is not
        `"function"`) or any Responses-only key (`previous_response_id`,
        `instructions`, `input`, `include`). `False` otherwise, e.g. payloads with
        only function-type tools or no tools.
    """
    tools = payload.get("tools")
    uses_builtin_tools = bool(tools) and any(_is_builtin_tool(tool) for tool in tools)
    return bool(uses_builtin_tools or _RESPONSES_ONLY_KEYS.intersection(payload))


def _get_attr(obj: Any, name: str, default: Any = None) -> Any:
    """Read a field from either a mapping or an object."""
    if isinstance(obj, Mapping):
        return obj.get(name, default)
    return getattr(obj, name, default)


def _model_dump(obj: Any) -> Any:
    """Return a plain representation of a possibly-pydantic object."""
    if hasattr(obj, "model_dump"):
        return obj.model_dump()
    return obj


def _convert_responses_usage(usage: Any) -> dict | None:
    """Convert Perplexity Responses API usage into LangChain `UsageMetadata`.

    Args:
        usage: The usage payload from a Responses API response (a mapping or a
            pydantic model).

    Returns:
        A `UsageMetadata` dict, or `None` when all token fields are absent.
    """
    if usage is None:
        return None
    if not isinstance(usage, Mapping):
        usage = _model_dump(usage)
    if not isinstance(usage, Mapping):
        return None

    input_tokens = usage.get("input_tokens")
    output_tokens = usage.get("output_tokens")
    total_tokens = usage.get("total_tokens")

    if input_tokens is None and output_tokens is None and total_tokens is None:
        return None

    if total_tokens is None and input_tokens is not None and output_tokens is not None:
        total_tokens = input_tokens + output_tokens

    return UsageMetadata(
        input_tokens=input_tokens or 0,
        output_tokens=output_tokens or 0,
        total_tokens=total_tokens
        if total_tokens is not None
        else (input_tokens or 0) + (output_tokens or 0),
    )


def _extract_responses_extras(response: Any) -> dict[str, Any]:
    """Collect Perplexity-specific extras from a Responses API response."""
    extras: dict[str, Any] = {}

    for attr in ("citations", "images", "related_questions"):
        value = _get_attr(response, attr)
        if value:
            extras[attr] = value

    search_results: list[Any] = []
    fetch_url_results: list[Any] = []
    for item in _get_attr(response, "output", None) or []:
        item_type = _get_attr(item, "type")
        if item_type == "search_results":
            search_results.extend(
                _model_dump(result) for result in _get_attr(item, "results", []) or []
            )
        elif item_type == "fetch_url_results":
            fetch_url_results.extend(
                _model_dump(content)
                for content in _get_attr(item, "contents", []) or []
            )
    if search_results:
        extras["search_results"] = search_results
    if fetch_url_results:
        extras["fetch_url_results"] = fetch_url_results

    return extras


def _extract_responses_content(response: Any) -> str:
    """Extract the text content from a Responses API response.

    Prefers the aggregated `output_text` convenience field, falling back to
    concatenating `output_text` parts of message output items.
    """
    output_text = _get_attr(response, "output_text")
    if output_text:
        return output_text

    texts: list[str] = []
    for item in _get_attr(response, "output", None) or []:
        if _get_attr(item, "type") != "message":
            continue
        for part in _get_attr(item, "content", []) or []:
            if _get_attr(part, "type") == "output_text":
                text = _get_attr(part, "text")
                if text:
                    texts.append(text)
    return "".join(texts)


def _convert_responses_to_chat_result(response: Any) -> ChatResult:
    """Convert a Perplexity Responses API response into a `ChatResult`."""
    content = _extract_responses_content(response)
    usage_metadata = _convert_responses_usage(_get_attr(response, "usage"))
    additional_kwargs = _extract_responses_extras(response)

    response_metadata: dict[str, Any] = {}
    if model_name := _get_attr(response, "model"):
        response_metadata["model_name"] = model_name
    if (status := _get_attr(response, "status")) is not None:
        response_metadata["status"] = status

    message = AIMessage(
        content=content,
        additional_kwargs=additional_kwargs,
        usage_metadata=usage_metadata,
        response_metadata=response_metadata,
        id=_get_attr(response, "id"),
    )
    return ChatResult(generations=[ChatGeneration(message=message)])


